17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.ArrayList;
25	import java.util.Collection;
26	import java.util.List;
27	
28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
41	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
42	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
43	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
52	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
75	    private static final int MAX_OWNERS_PER_CITY = 50;
76	
77	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
78	    private static final int MAX_OWNERS_PER_DAY = 100;
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    private final TelephoneNormalizer telephoneNormalizer;
89	
90	    private final AddressNormalizer addressNormalizer;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper,
96	                                 TelephoneNormalizer telephoneNormalizer,
97	                                 AddressNormalizer addressNormalizer) {
98	        this.clinicService = clinicService;
99	        this.ownerMapper = ownerMapper;
100	        this.petMapper = petMapper;
101	        this.visitMapper = visitMapper;
102	        this.telephoneNormalizer = telephoneNormalizer;
103	        this.addressNormalizer = addressNormalizer;
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
109	        Collection<Owner> owners;
110	        if (lastName != null) {
111	            owners = this.clinicService.findOwnerByLastName(lastName);
112	        } else {
113	            owners = this.clinicService.findAllOwners();
114	        }
115	        if (owners.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        normalizeAndValidate(ownerFieldsDto);
135	        HttpHeaders headers = new HttpHeaders();
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
138	        owner.setNamesakeCount(countNamesakes(owner));
139	        assignHousehold(owner, ownerFieldsDto);
140	        this.clinicService.saveOwner(owner);
141	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
142	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    /**
150	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
151	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
152	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
153	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
154	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
155	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
156	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
157	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
158	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly.
159	     *
160	     * @param ownerFieldsDto the incoming owner payload, mutated in place
161	     * @throws MissingOwnerFieldsException if any required field is missing or blank
162	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
163	     */
164	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
165	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
166	        validateRequiredFields(ownerFieldsDto);
167	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
168	        ownerFieldsDto.setTelephone(telephone);
169	        requireUniqueTelephone(telephone);
170	        requireUniqueHousehold(ownerFieldsDto);
171	        requireCityHasCapacity(ownerFieldsDto.getCity());
172	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
173	        ownerFieldsDto.setRegistrationDate(registrationDate);
174	        requireDailyLimitNotReached(registrationDate);
175	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
176	    }
177	
178	    /**
179	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
180	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
181	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
182	     *
183	     * @param ownerFieldsDto the incoming owner payload
184	     * @return the effective registration date rolled forward onto a business day
185	     */
186	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
187	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
188	        if (effective == null) {
189	            effective = LocalDate.now();
190	        }
191	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
192	            effective = effective.plusDays(1);
193	        }
194	        return effective;
195	    }
196	
197	    /**
198	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
199	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
200	     * further owner may be created for that day.
201	     *
202	     * @param registrationDate the adjusted business-day registration date of the owner being created
203	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
204	     */
205	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
206	        long createdThatDay = this.clinicService.findAllOwners().stream()
207	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
208	            .count();
209	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
210	            throw new DailyOwnerLimitExceededException(
211	                "the maximum number of owners for today has already been reached");
212	        }
213	    }
214	
215	    /**
216	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
217	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
218	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
219	     * city (e.g. {@code LON-SMI-0007}).
220	     *
221	     * @param city     the owner's city
222	     * @param lastName the owner's last name
223	     * @return the generated customer code
224	     */
225	    private String generateCustomerCode(String city, String lastName) {
226	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
227	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
228	        int sequence = (int) this.clinicService.findAllOwners().stream()
229	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
230	            .count() + 1;
231	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
232	    }
233	
234	    /**
235	     * Counts how many existing owners already share the given owner's first and last name, compared
236	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
237	     * create; it is zero when the owner's name is unique.
238	     *
239	     * @param owner the newly mapped owner about to be saved
240	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
241	     */
242	    private int countNamesakes(Owner owner) {
243	        String firstName = owner.getFirstName();
244	        String lastName = owner.getLastName();
245	        return (int) this.clinicService.findAllOwners().stream()
246	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
247	                && lastName.equalsIgnoreCase(existing.getLastName()))
248	            .count();
249	    }
250	
251	    /**
252	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
253	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
254	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
255	     *
256	     * @param ownerFieldsDto the owner payload to validate
257	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
258	     */
259	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
260	        List<String> missingFields = new ArrayList<>();
261	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
262	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
263	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
264	        requireText(missingFields, "city", ownerFieldsDto.getCity());
265	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
266	        if (!missingFields.isEmpty()) {
267	            throw new MissingOwnerFieldsException(missingFields);
268	        }
269	    }
270	
271	    private void requireText(List<String> missingFields, String fieldName, String value) {
272	        if (value == null || value.isBlank()) {
273	            missingFields.add(fieldName);
274	        }
275	    }
276	
277	    /**
278	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
279	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
280	     * (blank or {@code null}) email is left untouched, since the field is optional.
281	     *
282	     * @param email the raw email value from the request, may be {@code null}
283	     * @return the lower-cased email, or the original value when none was supplied
284	     */
285	    private String normalizeEmail(String email) {
286	        if (email == null || email.isBlank()) {
287	            return email;
288	        }
289	        return email.toLowerCase();
290	    }
291	
292	    /**
293	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
294	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
295	     * originally formatted.
296	     *
297	     * @param telephone the normalized telephone of the owner being created
298	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
299	     */
300	    private void requireUniqueTelephone(String telephone) {
301	        boolean inUse = this.clinicService.findAllOwners().stream()
302	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
303	            .anyMatch(telephone::equals);
304	        if (inUse) {
305	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
306	        }
307	    }
308	
309	    /**
310	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
311	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
312	     *
313	     * @param city the city of the owner being created
314	     * @throws OwnerCityFullException if the city already contains 50 or more owners
315	     */
316	    private void requireCityHasCapacity(String city) {
317	        long cityOwners = this.clinicService.findAllOwners().stream()
318	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
319	            .count();
320	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
321	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
322	        }
323	    }
324	
325	    /**
326	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
327	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
328	     *
329	     * @param ownerFieldsDto the incoming owner payload
330	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
331	     *                                 set {@code sharesHousehold}
332	     */
333	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
334	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
335	            return;
336	        }
337	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
338	            throw new DuplicateOwnerException(
339	                "an owner with the same last name and address already exists in this household");
340	        }
341	    }
342	
343	    /**
344	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
345	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
346	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
347	     * incidental formatting differences and abbreviation variants do not affect membership.
348	     *
349	     * @param ownerFieldsDto the incoming owner payload
350	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
351	     *         them; empty when none match
352	     */
353	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
354	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
355	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
356	        return this.clinicService.findAllOwners().stream()
357	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
358	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
359	            .toList();
360	    }
361	
362	    /**
363	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
364	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
365	     *
366	     * @param value the raw field value, may be {@code null}
367	     * @return the whitespace-collapsed value, or an empty string when {@code null}
368	     */
369	    private String collapseWhitespace(String value) {
370	        if (value == null) {
371	            return "";
372	        }
373	        return value.strip().replaceAll("\\s+", " ");
374	    }
375	
376	    /**
377	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
378	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
379	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
380	     * identifier is derived deterministically from the household's last name and address, so every member of the same
381	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
382	     * feature and still lack the identifier are backfilled so the whole household shares it.
383	     *
384	     * @param owner          the newly mapped owner about to be saved
385	     * @param ownerFieldsDto the incoming owner payload
386	     */
387	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
388	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
389	            return;
390	        }
391	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
392	        if (members.isEmpty()) {
393	            return;
394	        }
395	        String householdId = generateHouseholdId(ownerFieldsDto);
396	        owner.setHouseholdId(householdId);
397	        for (Owner member : members) {
398	            if (!householdId.equals(member.getHouseholdId())) {
399	                member.setHouseholdId(householdId);
400	                this.clinicService.saveOwner(member);
401	            }
402	        }
403	    }
404	
405	    /**
406	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
407	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
408	     * of those fields, it is identical for every owner in the same household and never changes over time.
409	     *
410	     * @param ownerFieldsDto the incoming owner payload
411	     * @return the household identifier
412	     */
413	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
414	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
415	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
416	        try {
417	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
418	            StringBuilder hex = new StringBuilder();
419	            for (int i = 0; i < 6; i++) {
420	                hex.append(String.format("%02X", digest[i]));
421	            }
422	            return "HH-" + hex;
423	        } catch (NoSuchAlgorithmException ex) {
424	            throw new IllegalStateException("SHA-256 is not available", ex);
425	        }
426	    }
427	
428	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
429	    @Override
430	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
431	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
432	        if (currentOwner == null) {
433	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
434	        }
435	        currentOwner.setAddress(ownerFieldsDto.getAddress());
436	        currentOwner.setCity(ownerFieldsDto.getCity());
437	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
438	        currentOwner.setLastName(ownerFieldsDto.getLastName());
439	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
440	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
441	        this.clinicService.saveOwner(currentOwner);
442	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
443	    }
444	
445	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
446	    @Transactional
447	    @Override
448	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
